#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

/*  "pos #n":  the slot on the board marked "n"
    "tile #n": the sliding square labeled "n"

    The board slots are numbered so:
        +-------------+
        |  5  0  1  2 |
        | 10  6  3  4 |
        | 11 12  7  8 |
        | 13 14  9 15 |
        +-------------+
    and in the solved state, tile #n ends at pos #n.

    Board is represented by a uint64_t consisting of 16 4-bit digits.
    Digit 0 (lowest bits) is the pos# of tile #0, etc., and digit #15
    is the pos# of the empty slot. E.g., digit 0 contains the current
    pos# of tile #0, the tile that should finish at the second slot
    on the top row.

    Because both pos# and tile# are re-ordered from the conventional
    ways, the solved board is represented by the position hex

            0xfedcba9876543210

    The connectivity graph, on the other hand, is hideous
    (see NEIGHBORS below).

    All of this scrambling just so that pattern database for subsets
    of tiles {0 ... 4}, {5 ... 9}, and {10 ... 15} can be looked up
    using consecutive indices. This can be a good example of losing
    legibility and flexibility for the sake of over-optimizations.
*/

typedef unsigned int state_t;
typedef unsigned char byte;

#define TOO_BIG 128
#define SIZE_DIST   0xfedcc
#define SIZE_SEEN   0xfedcbb
#define SIZE_Q      (1 << 19)
#define X 255
#define GOAL 0xfedcba9876543210ULL
#define DIGIT_GET(x, n) (((x)>>(4*(n))) & 15)
#define DIGIT(pos, val) ((uint64_t)(val) << (4*(pos)))

const int NEIGHBORS[16][5] = {
    {     5,  1,  6, X},  
    {     0,  2,  3, X},
    {     1,      4, X},
    { 1,  6,  4,  7, X},
    { 2,  3,      8, X},
    {         0, 10, X},
    { 0, 10,  3, 12, X},
    { 3, 12,  8,  9, X},
    { 4,  7,     15, X},
    { 7, 14, 15,     X},
    { 5,      6, 11, X},
    {10,     12, 13, X},
    { 6, 11,  7, 14, X},
    {11,     14,     X},
    {12, 13,      9, X},
    { 8,  9,         X} 
};

byte *PDB[3];

const char *trans_tile =      "\xf\x5\x0\x1\x2\xa\x6\x3\x4\xb\xc\x7\x8\xd\xe\x9",
           *rev_trans_tile =  "\x2\x3\x4\x7\x8\x1\x6\xb\xc\xf\x5\x9\xa\xd\xe\x0",
           *trans_pos =       "\x5\x0\x1\x2\xa\x6\x3\x4\xb\xc\x7\x8\xd\xe\x9\xf",
           *rev_trans_pos =   "\x1\x2\x3\x6\x7\x0\x5\xa\xb\xe\x4\x8\x9\xc\xd\xf";

// translate more readable 64-bit hex int to internal representation
uint64_t hex_to_board(uint64_t hex)
{
    uint64_t board = 0;
    for (int i = 0; i < 16; i++)
        board |= DIGIT(trans_tile[DIGIT_GET(hex, 15 - i)], trans_pos[i]);

    return board;
}

// print out board as a 4x4 grid
void show_board(uint64_t board)
{
    char s[32] = "       \n       \n       \n       ";
    for (int t = 0; t < 16; t++)
        s[2*rev_trans_pos[DIGIT_GET(board, t)]] = ((int)rev_trans_tile[t])["_123456789ABCDEF"];
    puts(s);
}

// 5-5-5 admissible pattern databases
static inline byte
pdb_heuristic(const uint64_t board)
{
    const uint64_t m = 0xfffff;
    return PDB[0][board&m] + PDB[1][(board >> 20)&m] + PDB[2][(board >> 40)&m];
}

byte *pdb_create(state_t tileset)
{
    // About half of dist array ends up blank, but you don't need to compute
    // the permutation rank to index into it. It's half megabyte of memory
    // well worth wasting.
    byte *dist = malloc(SIZE_DIST);
    byte *seen = malloc(SIZE_SEEN);

    memset(dist, 255, SIZE_DIST);
    memset(seen, 0, SIZE_SEEN);

    state_t *q = malloc(SIZE_Q*sizeof(state_t));
    int head = 0, tail = 0;
#   define PUSH(x, w)  { seen[x] = 1; q[tail++] = x|(w<<24); tail &= SIZE_Q - 1; }
#   define POP(x, w)   { x = q[head++]; w = x>>24; x&= 0xffffffU; head &= SIZE_Q - 1; }
    state_t root = (tileset << 4) | 15;
    byte cost;

    PUSH(root, 0);

    while (head != tail) {
        POP(root, cost);

        if (dist[root>>4] > cost)
            dist[root>>4] = cost;

        byte blank_pos = root & 15;

        const int *row = NEIGHBORS[blank_pos];
        for (int i = 0; row[i] != X; i++) {
            const int pos = row[i];
            int w = cost;
            state_t st = (root & ~15U) | pos;

            for (int j = 4; j < 24; j += 4)
                if (((st >> j) & 15) == pos) {
                    st ^= (pos^blank_pos)<<j;
                    ++w;
                    break;
                }

            if (!seen[st]) PUSH(st, w);
        }
    }

    free(seen);
    free(q);
    return dist;
}

byte *pdb_load_or_make(state_t tileset)
{
    char filename[32];
    byte *db;
    FILE *fp;

    sprintf(filename, "%05x.bin", tileset);

    if ((fp = fopen(filename, "rb"))) {
        db = malloc(SIZE_DIST);
        fread(db, SIZE_DIST, 1, fp);
        fclose(fp);
        printf("Loaded %d bytes from %s\n", SIZE_DIST, filename);
        return db;
    }

    printf("Creating pattern database %s\n", filename);
    db = pdb_create(tileset);

    if ((fp = fopen(filename, "wb"))) {
        fwrite(db, SIZE_DIST, 1, fp);
        fclose(fp);
        printf("Written %d bytes to %s\n", SIZE_DIST, filename);
    } else
        printf("Failed to write %s\n", filename);

    return db;
}

uint64_t path[TOO_BIG];
int n_path;
typedef struct { uint64_t board, lookup; int cost; } board_cost_s;

// given a series of boards, writes out corresponding up/down/what not instructions
void move_instructions(void)
{
    for (int i = 1, a = rev_trans_pos[path[0]>>60], b; i < n_path; i++, a = b) {
        b = rev_trans_pos[path[i] >> 60];
        putchar("U..L.R..D"[b - a + 4]);
    }
}

// recursive depth-first search for IDA*
int search(int g, int h, int bound, uint64_t lookup, int prev_blank)
{
    if (g + h > bound) return g + h;

    uint64_t root = path[n_path - 1];
    if (root == GOAL) return -1;

    int n_n = 0;
    board_cost_s neighbors[4];

    const uint64_t op = root >> 60, // old position
                   ot = 15;         // old tile #

    const int *row = NEIGHBORS[op];
    for (int n = 0; row[n] != X; n++) {
        const uint64_t np = row[n];     // new position
        if (np == prev_blank) continue;

        const uint64_t nt = (lookup >> (4*np))&15,                      // new tile #
                       b = root ^ (op^np)<<(4*ot) ^ (op^np)<<(4*nt),
                       l = lookup ^ (ot^nt)<<(4*np) ^ (ot^nt)<<(4*op);

        neighbors[n_n++] = (board_cost_s) {b, l, pdb_heuristic(b)};
    }

    for (int i = 0, j, k; i < n_n; i++) {
        for (k = i, j = i + 1; j < n_n; j++)
            if (neighbors[j].cost < neighbors[k].cost)
                k = j;

        if (k == i) continue;

        board_cost_s tmp = neighbors[k];
        neighbors[k] = neighbors[i];
        neighbors[i] = tmp;
    }

    int min_dist = TOO_BIG;

    for (int i = 0; i < n_n; i++) {
        path[n_path++] = neighbors[i].board;

        int res = search(g + 1, neighbors[i].cost, bound, neighbors[i].lookup, op);
        if (res == -1) return -1;
        if (res < min_dist) min_dist = res;

        --n_path;
    }

    return min_dist;
}

// boilerplate IDA*
int ida_star(uint64_t root)
{
    show_board(root);
    int h = pdb_heuristic(root), bound = h;

    uint64_t i, lookup = 0;
    for (i = 0; i < 16; i++)
        lookup |= i << (4*((root>>(4*i))&15));

    path[0] = root;
    n_path = 1;

    while (1) {
        bound = search(0, h, bound, lookup, 255);
        if (bound == TOO_BIG || bound == -1)
            return bound;
    }
}

