    MaxAntiPrime: u64 = 20
    fmt.print("\nFirst 20 anti-primes\n")
    fmt.println("--------------------")
    for (AntiPrimeCount < MaxAntiPrime) {
        n += 1
        Divisors = DivisorCount(n)
        if Divisors > MaxDivisors {
            fmt.print(n, " ")
            MaxDivisors = Divisors
