rotate <- function(v, n) {
  if (n == 0) v else c(tail(v, -n), head(v, n))
}

target_board <- matrix(1:16, nrow = 4, ncol = 4, byrow = TRUE)

rotate_rowcol <- function(n, direction) function(mat) {
  switch(
    direction, 
    "left" = mat[n, ] <- rotate(mat[n, ], 1), 
    "right" = mat[n, ] <- rotate(mat[n, ], -1),
    "up" = mat[, n] <- rotate(mat[, n], 1), 
    "down" = mat[, n] <- rotate(mat[, n], -1)
  )
  mat
}

sixteen_game <- function() {
  repeat {
    difficulty <- tolower(readline("Choose difficulty level (easy or hard): "))
    if (difficulty %in% c("easy", "hard")) break
    cat("\nThat's not a valid difficulty. Try again!\n")
  }
  maxmoves <- switch(difficulty, "easy" = 3, "hard" = 12)
  directions <- sample(c("left", "right", "up", "down"), maxmoves)
  funs <- mapply(rotate_rowcol, sample(4, maxmoves), directions)
  initial_board <- Reduce(function(x, f) f(x), funs, init = target_board)
  print(initial_board)
  turns <- 1
  while (!identical(initial_board, target_board)) {
    cat("\nTurn ", turns, "\n", sep = "")
    d <- "Choose a direction to rotate (up, down, left, or right): " |>
      readline() |>
      tolower()
    rc <- if (d %in% c("left", "right")) {
      "row" 
    } else if (d %in% c("up", "down")) {
      "column"
    } else {
      cat("\nThat's not a valid direction. Try again!\n")
      next
    }
    index <- paste("Enter a", rc, "number: ") |> readline() |> as.numeric()
    initial_board <- rotate_rowcol(index, d)(initial_board)
    print(initial_board)
    turns <- turns + 1
  }
  cat("\nWell done! You finished in", turns - 1, "move(s).\n")
}

