import scala.util.Random
import scala.util.control.Breaks._

object Main {
  def playOptimal(n: Int): Boolean = {
    val secretList = Random.shuffle((0 until n).toBuffer)

    for (i <- secretList.indices) {
      var prev = i
      breakable {
        for (_ <- 0 until secretList.size / 2) {
          if (secretList(prev) == i) {
            break()
          }
          prev = secretList(prev)
        }
        return false
      }
    }

    true
  }

  def playRandom(n: Int): Boolean = {
    val secretList = Random.shuffle((0 until n).toBuffer)

    for (i <- secretList.indices) {
      val trialList = Random.shuffle((0 until n).toBuffer)

      breakable {
        for (j <- 0 until trialList.size / 2) {
          if (trialList(j) == i) {
            break()
          }
        }
        return false
      }
    }

    true
  }

  def exec(n: Int, p: Int, play: Int => Boolean): Double = {
    var succ = 0.0
    for (_ <- 0 until n) {
      if (play(p)) {
        succ += 1
      }
    }
    (succ * 100.0) / n
  }

  def main(args: Array[String]): Unit = {
    val n = 100000
    val p = 100
    printf("# of executions: %,d\n", n)
    printf("Optimal play success rate: %f%%\n", exec(n, p, playOptimal))
    printf("Random play success rate: %f%%\n", exec(n, p, playRandom))
  }
}

import java.util.Random

import jline.console._

import scala.annotation.tailrec
import scala.collection.immutable
import scala.collection.parallel.immutable.ParVector

object FifteenPuzzle {
  def main(args: Array[String]): Unit = play()

  @tailrec def play(len: Int = 1000): Unit = if(gameLoop(Board.randState(len))) play(len)
  def gameLoop(board: Board): Boolean = {
    val read = new ConsoleReader()
    val km = KeyMap.keyMaps().get("vi-insert")
    val opMap = immutable.HashMap[Operation, Char](
      Operation.PREVIOUS_HISTORY -> 'u',
      Operation.BACKWARD_CHAR -> 'l',
      Operation.NEXT_HISTORY -> 'd',
      Operation.FORWARD_CHAR -> 'r')

    @tailrec
    def gloop(b: Board): Boolean = {
      println(s"\u001B[2J\u001B[2;0H$b\n←↑→↓q")
      if(b.isSolved) println("Solved!\nPlay again? (y/n)")

      read.readBinding(km) match{
        case Operation.SELF_INSERT => read.getLastBinding match{
          case "q" => false
          case "y" if b.isSolved => true
          case "n" if b.isSolved => false
          case _ => gloop(b)
        }
        case op: Operation if opMap.isDefinedAt(op) => gloop(b.move(opMap(op)))
        case _ => gloop(b)
      }
    }

    gloop(board)
  }

  case class Board(mat: immutable.HashMap[(Int, Int), Int], x: Int, y: Int) {
    def move(mvs: Seq[Char]): Board = mvs.foldLeft(this){case (b, m) => b.move(m)}
    def move(mov: Char): Board = mov match {
      case 'r' if x < 3 => Board(mat ++ Seq(((x, y), mat((x + 1, y))), ((x + 1, y), 0)), x + 1, y)
      case 'l' if x > 0 => Board(mat ++ Seq(((x, y), mat((x - 1, y))), ((x - 1, y), 0)), x - 1, y)
      case 'd' if y < 3 => Board(mat ++ Seq(((x, y), mat((x, y + 1))), ((x, y + 1), 0)), x, y + 1)
      case 'u' if y > 0 => Board(mat ++ Seq(((x, y), mat((x, y - 1))), ((x, y - 1), 0)), x, y - 1)
      case _ => this
    }

    def isSolved: Boolean = sumDist == 0
    def sumDist: Int = mat.to(LazyList).map{ case ((a, b), n) => if(n == 0) 6 - a - b else (a + b - ((n - 1) % 4) - ((n - 1) / 4)).abs }.sum

    override def toString: String = {
      val lst = mat.toVector.map { case ((a, b), n) => (4 * b + a, n) }.sortWith(_._1 < _._1).map(_._2)
      lst.map { n => if (n == 0) "  " else f"$n%2d" }.grouped(4).map(_.mkString(" ")).mkString("\n")
    }
  }

  object Board {
    val moves: Vector[Char] = Vector('r', 'l', 'd', 'u')

    def apply(config: Vector[Int]): Board = {
      val ind = config.indexOf(0)
      val formed = config.zipWithIndex.map { case (n, i) => ((i % 4, i / 4), n) }
      val builder = immutable.HashMap.newBuilder[(Int, Int), Int]
      builder ++= formed
      Board(builder.result, ind % 4, ind / 4)
    }

    def solveState: Board = apply((1 to 15).toVector :+ 0)
    def randState(len: Int, rand: Random = new Random()): Board = Iterator
      .fill(len)(moves(rand.nextInt(4)))
      .foldLeft(Board.solveState) { case (state, mv) => state.move(mv) }
  }
}

import scala.collection.mutable
case class Board(table: Array[Int], r: Int, c: Int, parent: List[String] = List()) {
  def cloneSwap(r: Int, c: Int, rr: Int, cc: Int) = {
    val cTable = table.clone
    // Fancy way to access table(r)(c) in linear array
    // Equivalent with cTable(r*4 + c) 
    cTable(r << 2 | c) = table(rr << 2 | cc)
    cTable(rr << 2 | cc) = table(r << 2 | c)
    cTable
  }
  def up() =
    if (r > 0) { Some(Board(cloneSwap(r, c, r - 1, c), r - 1, c, "u" :: parent))
    } else None
  def down() =
    if (r < 3) { Some(Board(cloneSwap(r, c, r + 1, c), r + 1, c, "d" :: parent))
    } else None
  def left() =
    if (c > 0) { Some(Board(cloneSwap(r, c, r, c - 1), r, c - 1, "l" :: parent))
    } else None
  def right() =
    if (c < 3) { Some(Board(cloneSwap(r, c, r, c + 1), r, c + 1, "r" :: parent))
    } else None
  def format: String = {
    table.sliding(4, 4).toList.map(_.map(i ⇒ f"$i%4d").mkString).mkString("\n")
  }
  // Manhattan distance
  def heuristic() = {
    val posF = Board.finalBoard.positionMap
    val posT = positionMap
    var res = 0;
    for (i ← 0 to 15) {
      val (x, y) = posF(i)
      val (xx, yy) = posT(i)
      res += (Math.abs(x - xx) + Math.abs(y - yy))
    }
    res
  }
  def key = table.mkString(",")
  def travelled() = parent.length
  // Find children/neighbours, flatten eliminates the empty boundaries
  def children: List[Board] = List(this.up(), this.down(), this.right(), this.left()).flatten
  // Map number to positions
  lazy val positionMap: Map[Int, (Int, Int)] = {
    val res = mutable.Map[Int, (Int, Int)]()
    for (x ← 0 to 3; y ← 0 to 3) {
      res(table(x << 2 | y)) = (x, y)
    }
    res.toMap
  }
}

import Board._
object Solver extends App {
  def solve(initBoard: Board, wTravel:Int, wHeuristic: Int ) {
    // Setup weights for the heuristic, more weight to heuristic faster but longer solution.
    def aStar(b:  Board) = wHeuristic * b.heuristic() + wTravel * b.travelled()
    implicit val ob = new Ordering[Board] {
      override def compare(x: Board, y: Board) = {
        aStar(y) - aStar(x)
      }
    }
    val start = System.currentTimeMillis()
    var found = false
    var head = initBoard
    val pq: mutable.PriorityQueue[Board] = new mutable.PriorityQueue()
    pq.enqueue(head)
    val visited = mutable.HashSet[String]()
    var explore = 0
    while (pq.nonEmpty && !found) {
      head = pq.dequeue()
      visited.add(head.key)
      if (!head.key.equals(finalBoard.key)) {
        val newChildren = head.children.filter(child ⇒ !visited.contains(child.key))
        visited ++= (newChildren.map(_.key))
        pq.enqueue(newChildren: _*)
        explore += 1
      } else found = true
      if (explore % 5000 == 0)
        println(s"# $explore: A* ${aStar(head)}  g:${head.travelled()} h:${head.heuristic()}")
    }
    if (found) {
      println(s"Exploring $explore states, solution with length ${head.parent.length}.")
      println(s"Weighted heuristic used $wHeuristic * heuristic + $wTravel * travel.")
      println(initBoard.format)
      println(head.parent.mkString.reverse)
    }
    println("Total time: " + (System.currentTimeMillis() - start) / 1000.0 + " seconds")
  }
  solve(startEasy, 4, 5)
  solve(startHard, 1, 2 )
}

