pub fn main(init: std.process.Init) !void {
    var stdout_writer = std.Io.File.stdout().writer(init.io, &.{});
    const stdout = &stdout_writer.interface;

    var doors = [_]bool{false} ** 101;
    var pass: u8 = 1;
